create or replace function public.toolbox_issues_bootstrap(p_workspace_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare caller uuid:=(select auth.uid()); role_name text; caps jsonb; usr jsonb; begin if caller is null or not private.toolbox_issues_host_member(p_workspace_id) then raise exception 'workspace access denied' using errcode='42501'; end if; select m.role into role_name from public.toolbox_issues_memberships m where m.workspace_id=p_workspace_id and m.user_id=caller and m.enabled; if role_name is null then if not exists(select 1 from public.toolbox_issues_memberships m where m.workspace_id=p_workspace_id and m.enabled) then role_name:='team_leader'; else role_name:='standard'; end if; insert into public.toolbox_issues_memberships(workspace_id,user_id,role,assigned_by) values(p_workspace_id,caller,role_name,caller) on conflict(workspace_id,user_id) do update set enabled=true,updated_at=now(); end if; caps:=case role_name when 'team_leader' then '["view_issues","create_issue","edit_issue","archive_issue","assign_issue","manage_subtasks","comment","attach","track_time","generate_reports","configure_roles"]'::jsonb when 'secretary' then '["view_issues","create_issue","edit_issue","archive_issue","assign_issue","manage_subtasks","comment","attach","track_time","generate_reports"]'::jsonb else '["view_issues","create_issue","edit_issue","archive_issue","assign_issue","manage_subtasks","comment","attach","track_time","generate_reports"]'::jsonb end; usr:=private.toolbox_issues_profile_json(caller)||jsonb_build_object('is_admin',role_name='team_leader'); return jsonb_build_object('role',role_name,'capabilities',caps,'user',usr); end $$; revoke execute on function public.toolbox_issues_bootstrap(uuid) from public,anon; grant execute on function public.toolbox_issues_bootstrap(uuid) to authenticated;;
